class ConfigError(Exception):
    pass

def parse_max_seats(env: dict) -> int:
    raw = env.get("MAX_SEATS", "6")
    try:
        seats = int(raw)
    except ValueError:
        raise ConfigError(f"MAX_SEATS must be a whole number, got {raw!r}") from None
    if seats < 1:
        raise ConfigError(f"MAX_SEATS must be at least 1, got {raw!r}")
    return seats

print(parse_max_seats({"MAX_SEATS": "4"}))
try:
    parse_max_seats({"MAX_SEATS": "four"})
except ConfigError as err:
    print("config error:", err)

slides.tests:
assert parse_max_seats({}) == 6, "With no MAX_SEATS the default should still be 6."
assert parse_max_seats({"MAX_SEATS": "4"}) == 4, "A valid MAX_SEATS of '4' should give 4."
for bad in ["four", "0"]:
    try:
        value = parse_max_seats({"MAX_SEATS": bad})
    except ConfigError as err:
        assert "MAX_SEATS" in str(err) and bad in str(err), "The ConfigError message should name MAX_SEATS and the bad value " + repr(bad) + ". It said: " + str(err)
    else:
        raise AssertionError("MAX_SEATS=" + repr(bad) + " returned " + repr(value) + " instead of raising ConfigError. Bad config must fail loudly at startup.")

