from store import MemoryStore

class WalletError(Exception):
    """Base class for every wallet rule."""

class InvalidAmount(WalletError):
    pass

class InsufficientFunds(WalletError):
    pass

class WalletService:
    def __init__(self, store):
        self.store = store

    def balance(self, user: str) -> int:
        return self.store.get(user)

    def top_up(self, user: str, amount: int) -> int:
        self._check(amount)
        self.store.set(user, self.balance(user) + amount)
        return self.balance(user)

    def pay(self, user: str, amount: int) -> int:
        self._check(amount)
        if amount > self.balance(user):
            raise InsufficientFunds(f"{user} has only {self.balance(user)} rupees")
        self.store.set(user, self.balance(user) - amount)
        return self.balance(user)

    @staticmethod
    def _check(amount: int) -> None:
        if amount <= 0:
            raise InvalidAmount(f"amount must be positive, got {amount}")

wallet = WalletService(MemoryStore())
print(wallet.top_up("riya", 500), wallet.pay("riya", 120))

